        min-width: 320px;
        background:
          radial-gradient(circle at top left, #1f3250 0, transparent 33rem),
          radial-gradient(circle at 85% 10%, #4a2541 0, transparent 28rem),
          linear-gradient(180deg, #080a0f 0%, #0d111a 44%, #080a0f 100%);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      a {
        color: inherit;
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--cyan);
        outline-offset: 4px;
      }

      img,
      svg {
        max-width: 100%;
      }

      .skip-link {
        position: fixed;
        left: 1rem;
        top: 1rem;
        z-index: 100;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--accent);
        color: var(--accent-text);
        font-weight: 800;
        padding: 0.75rem 1rem;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .container {
        width: min(100% - 2rem, var(--max));
        margin-inline: auto;
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 20;
        border-bottom: 1px solid var(--border);
        background: #080a0f;
      }

      .topbar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding-block: 0.9rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.65rem;
        color: var(--text);
        font-size: 1.05rem;
        font-weight: 900;
        letter-spacing: 0.09em;
        text-decoration: none;
        text-transform: uppercase;
        white-space: nowrap;
      }

      .brand-mark {
        display: grid;
        width: 2.5rem;
        height: 2.5rem;
        place-items: center;
        border: 1px solid var(--accent);
        border-radius: 0.9rem;
        background: linear-gradient(135deg, #f5bb39, #ff7a90);
        color: #111111;
        font-weight: 1000;
      }

      .nav-toggle {
        display: none;
        border: 1px solid var(--border);
        border-radius: 999px;
        background: var(--surface);
        color: var(--text);
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        padding: 0.65rem 0.9rem;
      }

      .primary-nav ul {
        display: flex;
        align-items: center;
        gap: 0.3rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .primary-nav a {
        display: inline-flex;
        border-radius: 999px;
        color: var(--muted);
        font-weight: 750;
        padding: 0.65rem 0.9rem;
        text-decoration: none;
      }

      .primary-nav a:hover {
        background: var(--surface-strong);
        color: var(--text);
      }

      .header-actions {
        display: flex;
        align-items: center;
        gap: 0.65rem;
      }

      .icon-link {
        display: inline-flex;
        min-height: 2.75rem;
        align-items: center;
        justify-content: center;
        border: 1px solid var(--border);
        border-radius: 999px;
        color: var(--text);
        font-weight: 800;
        padding: 0.65rem 0.9rem;
        text-decoration: none;
      }

      .hero {
        display: grid;
        grid-template-columns: minmax(0, 1.05fr) minmax(17rem, 0.95fr);
        gap: clamp(1.2rem, 4vw, 3rem);
        align-items: center;
        padding-block: clamp(3rem, 7vw, 6.5rem);
      }

      .eyebrow {
        display: inline-flex;
        width: fit-content;
        align-items: center;
        gap: 0.5rem;
        border: 1px solid var(--border);
        border-radius: 999px;
        background: var(--surface);
        color: var(--accent-strong);
        font-size: 0.9rem;
        font-weight: 850;
        letter-spacing: 0.08em;
        padding: 0.45rem 0.75rem;
        text-transform: uppercase;
      }

      h1,
      h2,
      h3 {
        line-height: 1.05;
      }

      h1 {
        max-width: 10ch;
        margin: 1rem 0;
        font-size: clamp(3rem, 9vw, 6.8rem);
        letter-spacing: -0.08em;
      }

      h2 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.4rem);
        letter-spacing: -0.045em;
      }

      h3 {
        margin: 0;
        font-size: 1.2rem;
      }

      p {
        color: var(--muted);
      }

      .hero-copy {
        max-width: 43rem;
        margin: 0 0 1.5rem;
        font-size: clamp(1.05rem, 2vw, 1.25rem);
      }

      .button-row {
        display: flex;
        flex-wrap: wrap;
        gap: 0.85rem;
      }

      .button {
        display: inline-flex;
        min-height: 3rem;
        align-items: center;
        justify-content: center;
        border: 1px solid var(--border);
        border-radius: 999px;
        cursor: pointer;
        font: inherit;
        font-weight: 900;
        padding: 0.8rem 1.1rem;
        text-decoration: none;
      }

      .button-primary {
        border-color: var(--accent);
        background: var(--accent);
        color: var(--accent-text);
      }

      .button-primary:hover {
        background: var(--accent-strong);
      }

      .button-secondary {
        background: var(--surface);
        color: var(--text);
      }

      .button-secondary:hover {
        background: var(--surface-strong);
      }

      .hero-card {
        min-width: 0;
        border: 1px solid var(--border);
        border-radius: 2rem;
        background:
          linear-gradient(145deg, #222f46, #0d121c 56%),
          var(--surface);
        box-shadow: 0 2rem 6rem var(--shadow);
        padding: clamp(1rem, 3vw, 1.6rem);
      }

      .product-spotlight {
        display: grid;
        gap: 1rem;
      }

      .visual-panel {
        min-height: 21rem;
        border: 1px solid #5e6f8e;
        border-radius: 1.5rem;
        background:
          radial-gradient(circle at 30% 30%, #ffcf5a 0 12%, transparent 13%),
          radial-gradient(circle at 68% 58%, #7de3ff 0 17%, transparent 18%),
          linear-gradient(145deg, #f889a1, #344666 48%, #111722);
        position: relative;
        overflow: hidden;
      }

      .visual-panel::after {
        position: absolute;
        right: -2rem;
        bottom: -3rem;
        width: 14rem;
        height: 14rem;
        border: 1.2rem solid #f7f8fb;
        border-radius: 999px;
        content: "";
      }

      .spotlight-details {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
      }

      .price {
        color: var(--text);
        font-size: 1.35rem;
        font-weight: 950;
      }

      .section {
        padding-block: clamp(2.6rem, 6vw, 5rem);
      }

      .section-header {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.4rem;
      }

      .section-header p {
        max-width: 32rem;
        margin: 0;
      }

      .grid {
        display: grid;
        gap: 1rem;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .product-card,
      .deal-card,
      .article-card,
      .newsletter {
        min-width: 0;
        border: 1px solid var(--border);
        border-radius: 1.4rem;
        background: var(--surface);
      }

      .product-card {
        display: flex;
        flex-direction: column;
        padding: 0.8rem;
      }

      .product-art {
        min-height: 13rem;
        border-radius: 1rem;
        background: var(--surface-strong);
      }

      .art-amber {
        background: radial-gradient(circle at 65% 35%, #ffcf5a 0 18%, transparent 19%), linear-gradient(135deg, #5d3820, #182437);
      }

      .art-cyan {
        background: radial-gradient(circle at 35% 45%, #7de3ff 0 16%, transparent 17%), linear-gradient(135deg, #183c4d, #232f43);
      }

      .art-rose {
        background: radial-gradient(circle at 55% 45%, #ff8ca3 0 18%, transparent 19%), linear-gradient(135deg, #4d1f31, #1b2435);
      }

      .art-green {
        background: radial-gradient(circle at 50% 45%, #92e6a7 0 16%, transparent 17%), linear-gradient(135deg, #1f4930, #1a2637);
      }

      .product-body {
        display: flex;
        flex: 1;
        flex-direction: column;
        gap: 0.75rem;
        padding: 1rem 0.35rem 0.35rem;
      }

      .meta-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
      }

      .tag {
        display: inline-flex;
        width: fit-content;
        border: 1px solid var(--border);
        border-radius: 999px;
        color: var(--muted);
        font-size: 0.85rem;
        font-weight: 800;
        padding: 0.25rem 0.55rem;
      }

      .product-body p {
        margin: 0;
      }

      .product-body .button {
        margin-top: auto;
        width: 100%;
      }

      .deals-grid {
        grid-template-columns: 1.2fr 0.8fr;
      }

      .deal-card {
        display: grid;
        min-height: 20rem;
        align-content: end;
        padding: clamp(1.2rem, 3vw, 1.6rem);
        position: relative;
        overflow: hidden;
      }

      .deal-card::before {
        position: absolute;
        inset: auto -4rem -5rem auto;
        width: 16rem;
        height: 16rem;
        border-radius: 999px;
        background: var(--accent);
        content: "";
      }

      .deal-card > * {
        position: relative;
      }

      .deal-card.featured {
        background: linear-gradient(135deg, #42283b, #121927 62%);
      }

      .deal-card.compact {
        background: linear-gradient(135deg, #1a3d4f, #121927 62%);
      }

      .deal-value {
        color: var(--accent-strong);
        font-size: clamp(2.8rem, 8vw, 5.8rem);
        font-weight: 1000;
        letter-spacing: -0.08em;
        line-height: 0.95;
      }

      .editorial-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .article-card {
        display: flex;
        flex-direction: column;
        overflow: hidden;
      }

      .article-art {
        min-height: 11rem;
        background:
          linear-gradient(135deg, #243958 25%, transparent 25% 50%, #ffcf5a 50% 72%, #111722 72%),
          var(--surface-strong);
      }

      .article-card:nth-child(2) .article-art {
        background:
          linear-gradient(145deg, #7de3ff 0 24%, #243958 24% 56%, #111722 56%),
          var(--surface-strong);
      }

      .article-card:nth-child(3) .article-art {
        background:
          radial-gradient(circle at 70% 35%, #ff8ca3 0 20%, transparent 21%),
          linear-gradient(145deg, #3e2849, #111722);
      }

      .article-body {
        display: grid;
        gap: 0.8rem;
        padding: 1.1rem;
      }

      .article-body p {
        margin: 0;
      }

      .text-link {
        color: var(--accent-strong);
        font-weight: 900;
        text-decoration-thickness: 0.12em;
        text-underline-offset: 0.2em;
      }

      .newsletter {
        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(16rem, 0.75fr);
        gap: 1.2rem;
        align-items: center;
        background: linear-gradient(135deg, #1c2638, #111722);
        padding: clamp(1.2rem, 4vw, 2rem);
      }

      .newsletter p {
        margin-bottom: 0;
      }

      .signup-form {
        display: grid;
        gap: 0.75rem;
      }

      .signup-form label {
        color: var(--text);
        font-weight: 850;
      }

      .input-row {
        display: flex;
        gap: 0.65rem;
      }

      input {
        min-width: 0;
        width: 100%;
        border: 1px solid var(--border);
        border-radius: 999px;
        background: #090d14;
        color: var(--text);
        font: inherit;
        padding: 0.85rem 1rem;
      }

      input::placeholder {
        color: #aeb8cb;
      }

      .site-footer {
        border-top: 1px solid var(--border);
        background: #080a0f;
        padding-block: 2rem;
      }

      .footer-grid {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }

      .footer-links {
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
      }

      .footer-links a {
        color: var(--muted);
        font-weight: 800;
      }

      .status {
        min-height: 1.5rem;
        color: var(--green);
        font-weight: 800;
      }

      @media (max-width: 880px) {
        .topbar {
          flex-wrap: wrap;
        }

        .nav-toggle {
          display: inline-flex;
        }

        .primary-nav {
          display: none;
          flex-basis: 100%;
          order: 3;
        }

        .primary-nav.is-open {
          display: block;
        }

        .primary-nav ul {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 0.5rem;
          padding-top: 0.75rem;
        }

        .primary-nav a {
          border: 1px solid var(--border);
          background: var(--surface);
        }

        .hero,
        .deals-grid,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .product-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }
      }

      @media (max-width: 560px) {
        .container {
          width: min(100% - 1rem, var(--max));
        }

        .header-actions {
          width: 100%;
          justify-content: space-between;
        }

        .primary-nav ul,
        .product-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .section-header,
        .spotlight-details,
        .input-row {
          align-items: stretch;
          flex-direction: column;
        }

        .button,
        .icon-link {
          width: 100%;
        }

        .visual-panel {
          min-height: 16rem;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        body,
        .site-header,
        .site-footer,
        .product-card,
        .deal-card,
        .article-card,
        .newsletter,
        .hero-card,
        .primary-nav a,
        .icon-link,
        input {
          border-color: CanvasText;
          background: Canvas;
          color: CanvasText;
        }

        .button,
        .nav-toggle,
        .skip-link {
          border: 2px solid ButtonBorder;
          background: ButtonFace;
          color: ButtonText;
        }

        .text-link,
        .eyebrow,
        .deal-value,
        .price,
        .status {
          color: CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const products = [
        {
          name: "Apex Trail Jacket",
          category: "Outerwear",
          price: "$148",
          description: "Weather-ready shell with city polish and packable warmth.",
          art: "art-amber"
        },
        {
          name: "Luma Carry Tote",
          category: "Accessories",
          price: "$82",
          description: "Structured recycled nylon tote sized for commute essentials.",
          art: "art-cyan"
        },
        {
          name: "Midnight Knit Set",
          category: "New Arrival",
          price: "$126",
          description: "Soft ribbed layers designed for lounge-to-dinner styling.",
          art: "art-rose"
        },
        {
          name: "Nova Runner",
          category: "Footwear",
          price: "$118",
          description: "Cloud-cushioned daily sneaker with reflective trim.",
          art: "art-green"
        }
      ];

      const articles = [
        {
          title: "The edited capsule for unpredictable spring weather",
          category: "Style Guide",
          description: "Layer smart with breathable shells, versatile knits, and accessories that work from 8 a.m. to late."
        },
        {
          title: "How our recycled nylon collection is made",
          category: "Behind the Brand",
          description: "A closer look at durable materials, lower-waste cutting, and the details that keep each piece in rotation."
        },
        {
          title: "Five essentials for a weekend away",
          category: "Travel Edit",
          description: "Packable staples with elevated texture, easy care, and enough polish for every reservation."
        }
      ];

      const Header = () => `
        <header class="site-header">
          <div class="container topbar">
            <a class="brand" href="#" aria-label="NOCTURNE Supply Co. home">
              <span class="brand-mark" aria-hidden="true">N</span>
              <span>NOCTURNE</span>
            </a>
            <button class="nav-toggle" type="button" aria-expanded="false" aria-controls="primary-navigation">
              Menu
            </button>
            <nav class="primary-nav" id="primary-navigation" aria-label="Primary navigation">
              <ul>
                <li><a href="#featured">Featured</a></li>
                <li><a href="#deals">Deals</a></li>
                <li><a href="#editorial">Editorial</a></li>
                <li><a href="#newsletter">Insider list</a></li>
              </ul>
            </nav>
            <div class="header-actions">
              <a class="icon-link" href="#featured">Shop now</a>
              <a class="icon-link" href="#cart" aria-label="Cart, 0 items">Cart 0</a>
            </div>
          </div>
        </header>
      `;

      const Hero = () => `
        <section class="container hero" aria-labelledby="hero-title">
          <div>
            <span class="eyebrow">Spring drop just landed</span>
            <h1 id="hero-title">Own the after-dark edit.</h1>
            <p class="hero-copy">
              Discover elevated everyday gear from NOCTURNE Supply Co., a retail destination for technical layers,
              refined accessories, and limited-run essentials built for city nights and weekend escapes.
            </p>
            <div class="button-row">
              <a class="button button-primary" href="#featured">Shop featured products</a>
              <a class="button button-secondary" href="#editorial">Read the editorial</a>
            </div>
          </div>
          <aside class="hero-card" aria-labelledby="spotlight-title">
            <div class="product-spotlight">
              <div class="visual-panel" aria-hidden="true"></div>
              <div class="spotlight-details">
                <div>
                  <span class="tag">Limited release</span>
                  <h2 id="spotlight-title">The Halo Weekender</h2>
                  <p>Water-resistant carryall with modular packing cubes included.</p>
                </div>
                <span class="price">$164</span>
              </div>
              <button class="button button-primary add-button" type="button" data-product="The Halo Weekender">
                Add The Halo Weekender to bag
              </button>
            </div>
          </aside>
        </section>
      `;

      const ProductCard = (product) => `
        <article class="product-card">
          <div class="product-art ${product.art}" aria-hidden="true"></div>
          <div class="product-body">
            <div class="meta-row">
              <span class="tag">${product.category}</span>
              <span class="price">${product.price}</span>
            </div>
            <h3>${product.name}</h3>
            <p>${product.description}</p>
            <button class="button button-secondary add-button" type="button" data-product="${product.name}">
              Add ${product.name} to bag
            </button>
          </div>
        </article>
      `;

      const FeaturedProducts = () => `
        <section class="container section" id="featured" aria-labelledby="featured-title">
          <div class="section-header">
            <div>
              <span class="eyebrow">Featured products</span>
              <h2 id="featured-title">Fresh pieces with staying power.</h2>
            </div>
            <p>Our current favorites combine functional finishes, premium handfeel, and silhouettes that layer cleanly.</p>
          </div>
          <div class="grid product-grid">
            ${products.map(ProductCard).join("")}
          </div>
        </section>
      `;

      const Deals = () => `
        <section class="container section" id="deals" aria-labelledby="deals-title">
          <div class="section-header">
            <div>
              <span class="eyebrow">Deals</span>
              <h2 id="deals-title">Member pricing for the midnight cart.</h2>
            </div>
            <p>Limited-time offers on bestsellers, bundles, and seasonal refreshes while stock lasts.</p>
          </div>
          <div class="grid deals-grid">
            <article class="deal-card featured">
              <span class="deal-value">30% off</span>
              <h3>Outerwear event</h3>
              <p>Save on rain shells, quilted vests, and packable insulation through Sunday.</p>
              <a class="button button-primary" href="#featured">Shop outerwear deals</a>
            </article>
            <article class="deal-card compact">
              <span class="deal-value">2 for $90</span>
              <h3>Core tee bundle</h3>
              <p>Mix heavyweight cotton crews and relaxed long sleeves in essential dark neutrals.</p>
              <a class="button button-secondary" href="#featured">Build a tee bundle</a>
            </article>
          </div>
        </section>
      `;

      const Editorial = () => `
        <section class="container section" id="editorial" aria-labelledby="editorial-title">
          <div class="section-header">
            <div>
              <span class="eyebrow">Editorial</span>
              <h2 id="editorial-title">Stories from the shop floor.</h2>
            </div>
            <p>Explore styling notes, material deep dives, and seasonal buying guides from the NOCTURNE team.</p>
          </div>
          <div class="grid editorial-grid">
            ${articles.map((article) => `
              <article class="article-card">
                <div class="article-art" aria-hidden="true"></div>
                <div class="article-body">
                  <span class="tag">${article.category}</span>
                  <h3>${article.title}</h3>
                  <p>${article.description}</p>
                  <a class="text-link" href="#newsletter">Read more in the insider list</a>
                </div>
              </article>
            `).join("")}
          </div>
        </section>
      `;

      const Newsletter = () => `
        <section class="container section" id="newsletter" aria-labelledby="newsletter-title">
          <div class="newsletter">
            <div>
              <span class="eyebrow">Insider list</span>
              <h2 id="newsletter-title">Get first access to drops and private deals.</h2>
              <p>Weekly edits, restock alerts, and editorial recommendations delivered every Thursday.</p>
            </div>
            <form class="signup-form" novalidate>
              <label for="email">Email address <span aria-hidden="true">*</span></label>
              <div class="input-row">
                <input id="email" name="email" type="email" autocomplete="email" required aria-describedby="email-help" placeholder="you@example.com">
                <button class="button button-primary" type="submit">Join the list</button>
              </div>
              <p id="email-help">Required. Use a valid email address, such as you@example.com.</p>
              <p class="status" aria-live="polite"></p>
            </form>
          </div>
        </section>
      `;

      const Footer = () => `
        <footer class="site-footer">
          <div class="container footer-grid">
            <p>&copy; 2026 NOCTURNE Supply Co. Built for refined everyday retail.</p>
            <nav aria-label="Footer navigation">
