                <a href="#deals">Offers</a>
                <a href="#editorial">Journal</a>
                <a href="#newsletter">Newsletter</a>
              </div>
            </nav>
          </div>
        </footer>
      `;

      const App = () => `
        ${Header()}
        <main id="main-content">
          ${Hero()}
          ${FeaturedProducts()}
          ${Deals()}
          ${Editorial()}
          ${Newsletter()}
        </main>
        ${Footer()}
        <div id="cart" class="container" aria-live="polite"></div>
